import { describe, it, expect } from "vitest";
import { parseGcodeEstimate, parseDuration } from "../src/gcode";

// Trimmed from a real OrcaSlicer 2.x output (header block + footer).
const ORCA = `; HEADER_BLOCK_START
; generated by OrcaSlicer 2.2.0 on 2026-10-01 at 12:00:00
; total layer number: 120
; filament_density: 1.24
; model printing time: 41m 25s; total estimated time: 47m 34s
; HEADER_BLOCK_END
G28
G1 X10 Y10
; ---PF-TAIL---
M104 S0
; filament used [mm] = 1234.56
; filament used [cm3] = 2.97
; filament used [g] = 3.68
; filament cost = 0.07
; total filament used [g] = 3.68
; total filament cost = 0.07
; total layers count = 120
; estimated printing time (normal mode) = 47m 34s
`;

const PRUSA_MULTI = `; filament used [mm] = 100.5, 200.25
; filament used [g] = 1.2, 2.3
; estimated printing time (normal mode) = 1d 2h 3m 4s
`;

describe("gcode estimates", () => {
  it("parses OrcaSlicer header + footer", () => {
    expect(parseGcodeEstimate(ORCA)).toEqual({
      print_time_s: 47 * 60 + 34,
      filament_mm: 1234.56,
      filament_g: 3.68,
      filament_cm3: 2.97,
      filament_cost: 0.07,
      layers: 120,
    });
  });

  it("sums per-extruder lists and handles day durations", () => {
    expect(parseGcodeEstimate(PRUSA_MULTI)).toMatchObject({ print_time_s: 93784, filament_mm: 300.75, filament_g: 3.5 });
  });

  it("falls back to Cura's ;TIME and returns nulls when nothing matches", () => {
    expect(parseGcodeEstimate(";FLAVOR:Marlin\n;TIME:3600\n;Filament used: 1.5m\n;LAYER_COUNT:50\n")).toMatchObject({
      print_time_s: 3600,
      filament_mm: 1500,
      layers: 50,
    });
    expect(parseGcodeEstimate("G28\n").print_time_s).toBeNull();
  });

  it("parses durations", () => {
    expect(parseDuration("2h 05m")).toBe(7500);
    expect(parseDuration("37s")).toBe(37);
    expect(parseDuration("n/a")).toBeNull();
  });
});
